int16_t rc_StickEdge(int16_t v, int16_t *state)
{
    int16_t target = *state;

    if(v >= RC_EDGE_ON)                                target = 1;
    else if(v <= -RC_EDGE_ON)                          target = -1;
    else if(v < RC_EDGE_OFF && v > -RC_EDGE_OFF)       target = 0;

    if(target != *state)
    {
        *state = target;
        return target;
    }
    return 0;
}


int16_t rc_Itoa(char *p, uint16_t v)
{
    char    tmp[6];
    int16_t n = 0;
    int16_t i;

    do
    {
        tmp[n++] = (char)('0' + (v % 10));
        v /= 10;
    }
    while(v);

    for(i = 0; i < n; i++)
        p[i] = tmp[n - 1 - i];

    p[n] = 0;
    return n;
}


int16_t rc_Cat(char *dst, int16_t n, const char *s, int16_t maxLen)
{
    while(*s && maxLen-- > 0)
        dst[n++] = *s++;
    dst[n] = 0;
    return n;
}


static int16_t TextLength(const char *s)
{
    int16_t n = 0;
    while(s[n] != 0) n++;
    return n;
}


// Centered text. `small` uses the 12 px font (card text, top bar).
void rc_DrawTextEx(const char *s, int16_t x, int16_t y, uint32_t fg,
                       uint32_t bg, bool small)
{
    int16_t len;

    if(s == NULL) return;
    len = TextLength(s);
    if(len == 0) return;

    if(small) Graphics_setFont(&g_sContext, &g_sFontCmss12b);
    Graphics_setForegroundColor(&g_sContext, fg);
    Graphics_setBackgroundColor(&g_sContext, bg);
    Graphics_drawStringCentered(&g_sContext, (int16_t *)s, len,
                                x, y, OPAQUE_TEXT);
    if(small) Graphics_setFont(&g_sContext, &g_sFontCmss20b);
}


void rc_DrawText(const char *s, int16_t x, int16_t y, uint32_t color)
{
    rc_DrawTextEx(s, x, y, color, C_BLACK, false);
}


void rc_DrawSmall(const char *s, int16_t x, int16_t y, uint32_t fg, uint32_t bg)
{
    rc_DrawTextEx(s, x, y, fg, bg, true);
}


void rc_Sfx(const Song *s)
{
    rc_sfxHold = 10;                             // staff shots wait for this to finish
    rc_stepBlock = 10;                           // so do footsteps
    Buzzer_PlaySfx(s);
}


// Low-priority effect: never cuts off whatever is already playing.
void rc_SfxSoft(const Song *s)
{
    if(!Buzzer_IsPlaying()) Buzzer_PlaySfx(s);
}
